ALTER TABLE categories ADD COLUMN description TEXT NULL AFTER name;
ALTER TABLE products ADD COLUMN short_description TEXT NULL AFTER name, ADD COLUMN sku VARCHAR(100) NULL AFTER slug, ADD COLUMN sub_category_id BIGINT UNSIGNED NULL AFTER category_id, ADD COLUMN selling_price DECIMAL(10,2) NOT NULL DEFAULT 0 AFTER description, ADD COLUMN strike_price DECIMAL(10,2) NULL AFTER selling_price, ADD COLUMN offer_price DECIMAL(10,2) NULL AFTER strike_price, ADD COLUMN weight_unit VARCHAR(20) NULL AFTER weight, ADD COLUMN manage_inventory TINYINT(1) NOT NULL DEFAULT 1 AFTER stock_quantity, ADD COLUMN low_stock_threshold INT UNSIGNED NOT NULL DEFAULT 5 AFTER manage_inventory, ADD COLUMN stock_status ENUM('IN_STOCK','LOW_STOCK','OUT_OF_STOCK') NOT NULL DEFAULT 'OUT_OF_STOCK' AFTER low_stock_threshold, ADD COLUMN featured TINYINT(1) NOT NULL DEFAULT 0 AFTER status, ADD COLUMN main_image VARCHAR(500) NULL AFTER image;
CREATE TABLE IF NOT EXISTS sub_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, description TEXT NULL, sort_order INT UNSIGNED NOT NULL DEFAULT 0, status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_sub_category_parent FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS product_variations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, variation_name VARCHAR(160) NOT NULL, sku VARCHAR(100) NULL, weight DECIMAL(10,2) NULL, weight_unit VARCHAR(20) NULL, selling_price DECIMAL(10,2) NOT NULL DEFAULT 0, strike_price DECIMAL(10,2) NULL, stock_quantity INT UNSIGNED NOT NULL DEFAULT 0, status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, image_path VARCHAR(500) NOT NULL, is_primary TINYINT(1) NOT NULL DEFAULT 0, sort_order INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(60) NOT NULL UNIQUE, customer_name VARCHAR(180) NOT NULL, email VARCHAR(190) NULL, phone VARCHAR(40) NOT NULL, shipping_address TEXT NOT NULL, subtotal DECIMAL(10,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(10,2) NOT NULL DEFAULT 0, delivery_charge DECIMAL(10,2) NOT NULL DEFAULT 0, total_amount DECIMAL(10,2) NOT NULL DEFAULT 0, payment_method VARCHAR(40) NULL, payment_status ENUM('PENDING','PAID','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING', order_status ENUM('NEW','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED') NOT NULL DEFAULT 'NEW', delivery_type VARCHAR(40) NULL, notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, product_variation_id BIGINT UNSIGNED NULL, product_name_snapshot VARCHAR(180) NOT NULL, variation_snapshot VARCHAR(180) NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(10,2) NOT NULL, line_total DECIMAL(10,2) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, title VARCHAR(180) NOT NULL, description TEXT NULL, discount_type ENUM('PERCENTAGE','FIXED') NOT NULL, discount_value DECIMAL(10,2) NOT NULL DEFAULT 0, min_order_amount DECIMAL(10,2) NOT NULL DEFAULT 0, max_discount DECIMAL(10,2) NULL, start_date DATE NULL, expiry_date DATE NULL, usage_limit INT UNSIGNED NOT NULL DEFAULT 0, per_user_limit INT UNSIGNED NOT NULL DEFAULT 0, status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
